(function(){
  // Local shim: attempt to load xml2js from CDN as a fallback.
  // If your environment has the real file, replace this with the distribution copy.
  try {
    var s = document.createElement('script');
    s.src = 'https://cdnjs.cloudflare.com/ajax/libs/xml2js/0.5.0/xml2js.min.js';
    s.onload = function(){ console.info('Loaded xml2js from CDN fallback'); };
    s.onerror = function(){ console.error('Failed to load xml2js from CDN fallback'); };
    document.head.appendChild(s);
  } catch (e) {
    console.error('xml2js shim failed', e);
  }
})();
